private final void handleExternalNavigation() {
    if (getIntent().getBooleanExtra(EXTRA_GO_TO_HAREM, false)) {
        getIntent().removeExtra(EXTRA_GO_TO_HAREM);
        switchToHaremFragment();
    }
    if (getIntent().getBooleanExtra(EXTRA_GO_TO_SQUARE, false)) {
        getIntent().removeExtra(EXTRA_GO_TO_SQUARE);
        switchToSquareFragment();
    }
}
